//! Raster primitives against the pygame 2.6.1 goldens in `golden/raster`
//! (generated by `tools/pygame-golden/raster/gen_raster.py`).

use std::collections::{BTreeMap, BTreeSet};
use std::fs;
use std::path::{Path, PathBuf};

use banquo_canvas::raster::blend;
use banquo_canvas::{IRect, Rgba8, Surface};
use sha2::{Digest, Sha256};

const WHITE: Rgba8 = Rgba8::new(255, 255, 255, 255);

fn golden(rel: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/golden")
        .join(rel)
}

/// A PNG as (width, height, channels, bytes); 8-bit gray or RGB only.
fn read_png(path: &Path) -> (u32, u32, usize, Vec<u8>) {
    let file = fs::File::open(path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    let decoder = png::Decoder::new(std::io::BufReader::new(file));
    let mut reader = decoder.read_info().expect("png header");
    let mut buf = vec![0; reader.output_buffer_size().expect("png size")];
    let info = reader.next_frame(&mut buf).expect("png frame");
    assert_eq!(info.bit_depth, png::BitDepth::Eight, "{}", path.display());
    let channels = match info.color_type {
        png::ColorType::Grayscale => 1,
        png::ColorType::Rgb => 3,
        other => panic!("{}: unexpected colour type {other:?}", path.display()),
    };
    buf.truncate(info.width as usize * info.height as usize * channels);
    (info.width, info.height, channels, buf)
}

/// A white-on-transparent mask PNG (gray v) as an alpha surface of (v,v,v,v).
fn load_mask(path: &Path) -> Surface {
    let (w, h, ch, data) = read_png(path);
    assert_eq!(ch, 1, "{}", path.display());
    let mut s = Surface::new(w, h, true);
    for (i, &v) in data.iter().enumerate() {
        let (x, y) = ((i as u32 % w) as i32, (i as u32 / w) as i32);
        s.set(x, y, Rgba8::new(v, v, v, v));
    }
    s
}

/// An RGB PNG as an opaque surface.
fn load_rgb(path: &Path) -> Surface {
    let (w, h, ch, data) = read_png(path);
    assert_eq!(ch, 3, "{}", path.display());
    let mut s = Surface::new(w, h, false);
    for (i, &[r, g, b]) in data.as_chunks::<3>().0.iter().enumerate() {
        let (x, y) = ((i as u32 % w) as i32, (i as u32 / w) as i32);
        s.set(x, y, Rgba8::rgb(r, g, b));
    }
    s
}

/// Differing RGBA bytes, with an ASCII picture of the first mismatch.
fn diff_bytes(name: &str, got: &Surface, want: &Surface) -> usize {
    assert_eq!(
        (got.width(), got.height()),
        (want.width(), want.height()),
        "{name}: size"
    );
    let n = got
        .as_bytes()
        .iter()
        .zip(want.as_bytes())
        .filter(|(a, b)| a != b)
        .count();
    if n > 0 {
        eprintln!("{name}: {n} differing bytes (got / want)");
        for y in 0..got.height() as i32 {
            let row = |s: &Surface| -> String {
                (0..s.width() as i32)
                    .map(|x| if s.get(x, y).unwrap().a > 0 { '#' } else { '.' })
                    .collect()
            };
            eprintln!("{}   {}", row(got), row(want));
        }
    }
    n
}

fn files_under(dir: &Path, out: &mut Vec<PathBuf>) {
    for e in fs::read_dir(dir).unwrap() {
        let p = e.unwrap().path();
        if p.is_dir() {
            files_under(&p, out);
        } else {
            out.push(p);
        }
    }
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

#[test]
fn golden_manifest_matches_files() {
    for set in ["raster", "crt"] {
        let root = golden(set);
        let manifest: serde_json::Value =
            serde_json::from_slice(&fs::read(root.join("MANIFEST.json")).unwrap()).unwrap();
        let header = &manifest["header"];
        assert_eq!(header["python"], "3.13.11", "{set}");
        assert_eq!(header["pygame"], "2.6.1", "{set}");
        assert_eq!(header["sdl"], "2.28.4", "{set}");
        let listed: BTreeMap<String, String> = manifest["files"]
            .as_object()
            .unwrap()
            .iter()
            .map(|(k, v)| (k.clone(), v.as_str().unwrap().to_owned()))
            .collect();
        let mut on_disk = Vec::new();
        files_under(&root, &mut on_disk);
        let on_disk: BTreeSet<String> = on_disk
            .iter()
            .map(|p| {
                p.strip_prefix(&root)
                    .unwrap()
                    .to_string_lossy()
                    .replace('\\', "/")
            })
            .filter(|p| p != "MANIFEST.json")
            .collect();
        assert_eq!(
            on_disk,
            listed.keys().cloned().collect::<BTreeSet<_>>(),
            "{set}: files on disk vs manifest"
        );
        for (rel, want) in &listed {
            let got = hex(&Sha256::digest(fs::read(root.join(rel)).unwrap()));
            assert_eq!(&got, want, "{set}/{rel}");
        }
        println!(
            "manifest {set}: {}/{} sha256 match",
            listed.len(),
            listed.len()
        );
    }
}

#[test]
fn blend_matches_pygame() {
    let doc: serde_json::Value =
        serde_json::from_slice(&fs::read(golden("raster/blend.json")).unwrap()).unwrap();
    let samples: Vec<[u8; 10]> = doc["samples"]
        .as_array()
        .unwrap()
        .iter()
        .map(|s| {
            let v: Vec<u8> = s
                .as_array()
                .unwrap()
                .iter()
                .map(|n| u8::try_from(n.as_u64().unwrap()).unwrap())
                .collect();
            v.try_into().unwrap()
        })
        .collect();
    let n = samples.len();
    assert!(n >= 6912, "only {n} samples");
    let alphas: BTreeSet<u8> = samples.iter().map(|s| s[3]).collect();
    let need: BTreeSet<u8> = [1, 35, 64, 108, 128, 200, 210, 254, 255].into();
    assert!(need.is_subset(&alphas), "alphas {alphas:?}");

    // The same samples through Surface::blit: an SRCALPHA source row onto an
    // opaque destination row.
    let mut src = Surface::new(n as u32, 1, true);
    let mut dst = Surface::new(n as u32, 1, false);
    for (i, s) in samples.iter().enumerate() {
        src.set(i as i32, 0, Rgba8::new(s[0], s[1], s[2], s[3]));
        dst.set(i as i32, 0, Rgba8::rgb(s[4], s[5], s[6]));
    }
    dst.blit(&src, 0, 0);

    let mut exact = 0;
    for (i, s) in samples.iter().enumerate() {
        let want = Rgba8::rgb(s[7], s[8], s[9]);
        let by_fn = Rgba8::rgb(
            blend(s[0], s[4], s[3]),
            blend(s[1], s[5], s[3]),
            blend(s[2], s[6], s[3]),
        );
        let by_blit = dst.get(i as i32, 0).unwrap();
        if by_fn == want && by_blit == want {
            exact += 1;
        } else {
            eprintln!("sample {i} {s:?}: blend {by_fn:?} blit {by_blit:?}");
        }
    }
    println!("blend {exact}/{n} exact");
    assert_eq!(exact, n);
    assert_eq!(blend(0, 255, 128), 127);
}

/// Every golden mask file whose name starts with `prefix`.
fn masks(prefix: &str) -> Vec<(String, PathBuf)> {
    let mut out: Vec<_> = fs::read_dir(golden("raster/masks"))
        .unwrap()
        .map(|e| e.unwrap().path())
        .filter_map(|p| {
            let stem = p.file_stem()?.to_str()?.to_owned();
            stem.starts_with(prefix).then_some((stem, p))
        })
        .collect();
    out.sort();
    out
}

fn num(s: &str) -> i32 {
    s.parse().unwrap()
}

#[test]
fn rect_masks_match_pygame() {
    let mut exact = 0;
    let all = masks("rect-");
    let mut seen = BTreeSet::new();
    for (name, path) in &all {
        // rect-<w>x<h>-r<radius>-w<width>
        let parts: Vec<&str> = name.split('-').collect();
        let (w, h) = parts[1].split_once('x').unwrap();
        let (w, h) = (num(w), num(h));
        let radius = num(&parts[2][1..]);
        let width = num(&parts[3][1..]);
        seen.insert((w, h, radius, width));
        let want = load_mask(path);
        let mut got = Surface::new(want.width(), want.height(), true);
        got.draw_rect(IRect::new(2, 2, w, h), WHITE, width, radius);
        if diff_bytes(name, &got, &want) == 0 {
            exact += 1;
        }
    }
    println!("rect masks {exact}/{} exact", all.len());
    // radii 0-10 x widths 0-3 x 5 sizes.
    assert_eq!(all.len(), 220);
    assert_eq!(seen.len(), 220);
    for size in [(6, 6), (38, 38), (67, 36), (67, 52), (71, 56)] {
        for r in 0..=10 {
            for wd in 0..=3 {
                assert!(seen.contains(&(size.0, size.1, r, wd)));
            }
        }
    }
    assert_eq!(exact, all.len());
}

/// A circle mask: (name, path, radius, width).
type CircleMask = (String, PathBuf, i32, i32);

/// The circle masks.
fn circle_masks() -> Vec<CircleMask> {
    masks("circle-")
        .into_iter()
        .map(|(name, path)| {
            // circle-r<radius>-w<width>, centred on a 16x16 surface
            let parts: Vec<&str> = name.split('-').collect();
            let radius = num(&parts[1][1..]);
            let width = num(&parts[2][1..]);
            (name, path, radius, width)
        })
        .collect()
}

/// A ring thinner than its radius (`1 < width < radius`).
fn is_thick_ring(radius: i32, width: i32) -> bool {
    width > 1 && width < radius
}

fn circle_exact(masks: &[CircleMask]) -> usize {
    let mut exact = 0;
    for (name, path, radius, width) in masks {
        let want = load_mask(path);
        let mut got = Surface::new(want.width(), want.height(), true);
        got.draw_circle(8, 8, *radius, *width, WHITE);
        if diff_bytes(name, &got, &want) == 0 {
            exact += 1;
        }
    }
    exact
}

/// Filled circles, 1 px circles and `width >= radius` (drawn filled) for
/// radii 1-6.
#[test]
fn circle_masks_match_pygame() {
    let all = circle_masks();
    let radii: BTreeSet<i32> = all.iter().map(|m| m.2).collect();
    assert_eq!(radii, (1..=6).collect());
    let exact_set: Vec<_> = all
        .into_iter()
        .filter(|m| !is_thick_ring(m.2, m.3))
        .collect();
    for r in 1..=6 {
        assert!(exact_set.iter().any(|m| m.2 == r && m.3 == 0));
        assert!(exact_set.iter().any(|m| m.2 == r && m.3 == 1));
    }
    let exact = circle_exact(&exact_set);
    println!("circle masks {exact}/{} exact", exact_set.len());
    assert_eq!(exact, exact_set.len());
}

/// Rings with `1 < width < radius`. pygame 2.6.1 draws these with a
/// thickness rule this crate does not reproduce yet (`draw_circle` draws
/// the filled circle minus the filled inner circle), so the masks are kept
/// as the reference for that work and this check is not part of the gate.
#[test]
#[ignore = "thick rings are not pixel-exact against pygame yet"]
fn thick_circle_masks_match_pygame() {
    let thick: Vec<_> = circle_masks()
        .into_iter()
        .filter(|m| is_thick_ring(m.2, m.3))
        .collect();
    let exact = circle_exact(&thick);
    println!("thick circle masks {exact}/{} exact", thick.len());
    assert_eq!(exact, thick.len());
}

/// A 1 px golden line: (name, start, end).
type Line = (&'static str, (i32, i32), (i32, i32));

/// The 1 px lines of the generator's LINES table.
const LINES: &[Line] = &[
    ("h-right", (2, 5), (40, 5)),
    ("h-left", (40, 9), (2, 9)),
    ("h-point", (7, 13), (7, 13)),
    ("v-down", (4, 2), (4, 35)),
    ("v-up", (9, 35), (9, 2)),
    ("d-45-se", (2, 2), (30, 30)),
    ("d-45-nw", (30, 30), (2, 2)),
    ("d-45-ne", (2, 35), (35, 2)),
    ("d-45-sw", (35, 2), (2, 35)),
    ("d-shallow-e", (3, 4), (44, 17)),
    ("d-shallow-w", (44, 17), (3, 4)),
    ("d-steep-s", (5, 1), (14, 38)),
    ("d-steep-n", (14, 38), (5, 1)),
    ("d-odd-1", (1, 1), (46, 2)),
    ("d-odd-2", (1, 38), (2, 1)),
    ("d-odd-3", (0, 0), (47, 39)),
    ("d-odd-4", (47, 0), (0, 39)),
    ("d-odd-5", (10, 20), (37, 31)),
    ("d-odd-6", (37, 31), (10, 20)),
    ("d-odd-7", (20, 3), (29, 36)),
];

#[test]
fn line_masks_match_pygame() {
    let all = masks("line-");
    assert_eq!(all.len(), LINES.len());
    let mut exact = 0;
    for &(name, (x1, y1), (x2, y2)) in LINES {
        let path = golden(&format!("raster/masks/line-{name}.png"));
        let want = load_mask(&path);
        let mut got = Surface::new(want.width(), want.height(), true);
        got.draw_line(x1, y1, x2, y2, WHITE);
        if diff_bytes(name, &got, &want) == 0 {
            exact += 1;
        }
    }
    for kind in ["h-", "v-", "d-"] {
        assert!(LINES.iter().any(|l| l.0.starts_with(kind)));
    }
    println!("line masks {exact}/{} exact", LINES.len());
    assert_eq!(exact, LINES.len());
}

/// The generator's 50x45 clip sprite.
fn clip_sprite() -> Surface {
    let mut s = Surface::new(50, 45, true);
    for y in 0..45 {
        for x in 0..50 {
            let c = Rgba8::new(
                ((x * 5) % 256) as u8,
                ((y * 5) % 256) as u8,
                ((x * y) % 256) as u8,
                ((x * 7 + y * 3) % 256) as u8,
            );
            s.set(x, y, c);
        }
    }
    s
}

fn draw_clip(s: &mut Surface, prim: &str, ox: i32, oy: i32, sprite: &Surface) {
    match prim {
        "fill_rect" => s.fill_rect(IRect::new(ox, oy, 50, 45), Rgba8::rgb(200, 60, 20)),
        "draw_rect" => {
            s.draw_rect(IRect::new(ox, oy, 50, 45), Rgba8::rgb(220, 200, 40), 3, 8);
            s.draw_rect(
                IRect::new(ox + 6, oy + 6, 38, 33),
                Rgba8::rgb(40, 200, 220),
                0,
                5,
            );
        }
        "draw_circle" => {
            s.draw_circle(ox + 3, oy + 3, 6, 0, Rgba8::rgb(250, 250, 250));
            s.draw_circle(ox + 43, oy + 43, 6, 1, Rgba8::rgb(250, 120, 250));
            s.draw_circle(ox + 44, oy + 3, 5, 1, Rgba8::rgb(120, 250, 250));
        }
        "draw_line" => {
            s.draw_line(ox, oy, ox + 50, oy + 45, Rgba8::rgb(255, 255, 0));
            s.draw_line(ox, oy + 1, ox + 60, oy + 1, Rgba8::rgb(0, 255, 255));
            s.draw_line(ox + 2, oy, ox + 2, oy + 50, Rgba8::rgb(255, 0, 255));
            s.draw_line(ox + 49, oy, ox, oy + 44, Rgba8::rgb(255, 128, 0));
        }
        "blit" => s.blit(sprite, ox, oy),
        other => panic!("unknown primitive {other}"),
    }
}

#[test]
fn clipping_matches_pygame() {
    let sprite = clip_sprite();
    let prims = ["fill_rect", "draw_rect", "draw_circle", "draw_line", "blit"];
    let offsets = [(-3, -2), (-40, -40), (62, 47)];
    let mut exact = 0;
    for prim in prims {
        for (ox, oy) in offsets {
            let name = format!("{prim}_{ox}_{oy}");
            let want = load_rgb(&golden(&format!("raster/clip/{name}.png")));
            let mut got = Surface::new(64, 48, false);
            got.fill(Rgba8::rgb(16, 32, 48));
            draw_clip(&mut got, prim, ox, oy, &sprite);
            let px = (0..48)
                .flat_map(|y| (0..64).map(move |x| (x, y)))
                .filter(|&(x, y)| got.get(x, y) != want.get(x, y))
                .count();
            if px == 0 {
                exact += 1;
            } else {
                eprintln!("{name}: {px} differing pixels");
            }
        }
    }
    let total = prims.len() * offsets.len();
    let on_disk = fs::read_dir(golden("raster/clip")).unwrap().count();
    assert_eq!(on_disk, total);
    println!("clip {exact}/{total} exact");
    assert_eq!(exact, total);
}

#[test]
fn far_offsets_do_not_panic() {
    let sprite = clip_sprite();
    let mut s = Surface::new(64, 48, true);
    for (ox, oy) in [
        (i32::MIN / 4, i32::MIN / 4),
        (i32::MAX / 4, -7),
        (-1000, 1000),
    ] {
        s.fill_rect(IRect::new(ox, oy, 50, 45), WHITE);
        s.draw_rect(IRect::new(ox, oy, 50, 45), WHITE, 3, 8);
        s.draw_circle(ox, oy, 6, 2, WHITE);
        s.draw_line(ox, oy, ox + 50, oy + 45, WHITE);
        s.blit(&sprite, ox, oy);
        s.blit_mask(&sprite, ox, oy, WHITE);
    }
    assert!(s.as_bytes().iter().all(|&b| b == 0));
}

#[test]
fn blit_mask_equals_blitting_a_coloured_sprite() {
    let sprite = clip_sprite();
    let c = Rgba8::new(200, 30, 90, 255);
    let mut coloured = Surface::new(50, 45, true);
    for y in 0..45 {
        for x in 0..50 {
            let a = sprite.get(x, y).unwrap().a;
            coloured.set(x, y, Rgba8::new(c.r, c.g, c.b, a));
        }
    }
    let mut a = Surface::new(64, 48, false);
    a.fill(Rgba8::rgb(16, 32, 48));
    let mut b = a.clone();
    a.blit_mask(&sprite, 5, 3, c);
    b.blit(&coloured, 5, 3);
    assert_eq!(a, b);
}
